import type { AppContext } from '../../context.js';
import { exec, one } from '../../db/pool.js';
import { WebmailError, type WebmailMailbox } from './webmail.interface.js';

interface CredentialRow {
  mailbox_id: string;
  engine_key_id: string;
  secret_encrypted: string;
}

/**
 * Returns the mailbox-scoped API key used by the webmail proxy, creating it on first use.
 *
 * The secret is generated by the mail engine and stored encrypted (AES-256-GCM). It is never sent
 * to a browser, written to a job payload or logged. Each mailbox has exactly one key; deleting the
 * mailbox cascades the local row and the engine removes the key with the account.
 */
export async function ensureWebmailCredential(ctx: AppContext, mailbox: { id: string; mail_engine_account_id: string | null }): Promise<string> {
  if (!mailbox.mail_engine_account_id) throw new WebmailError('unavailable', 'This mailbox is not ready on the mail server yet.');
  const existing = await one<CredentialRow>(ctx.db, 'SELECT mailbox_id, engine_key_id, secret_encrypted FROM mailbox_webmail_credentials WHERE mailbox_id = ?', [mailbox.id]);
  if (existing) {
    try {
      return ctx.secrets.decrypt(existing.secret_encrypted);
    } catch {
      // The application encryption key changed: the stored secret is unusable, so revoke and recreate.
      await ctx.mail.deleteMailboxWebmailKey(mailbox.mail_engine_account_id, existing.engine_key_id).catch(() => undefined);
      await exec(ctx.db, 'DELETE FROM mailbox_webmail_credentials WHERE mailbox_id = ?', [mailbox.id]);
    }
  }
  const key = await ctx.mail.createMailboxWebmailKey(mailbox.mail_engine_account_id, `ARTHVEX webmail proxy (${mailbox.id})`);
  const inserted = await exec(
    ctx.db,
    `INSERT INTO mailbox_webmail_credentials (mailbox_id, engine_key_id, secret_encrypted) VALUES (?, ?, ?)
     ON DUPLICATE KEY UPDATE mailbox_id = mailbox_id`,
    [mailbox.id, key.keyId, ctx.secrets.encrypt(key.secret)],
  );
  if (inserted.affectedRows === 0) {
    // Another request created the credential first. Revoke the key this request just created so it
    // cannot linger as an unused credential, then use the stored one.
    await ctx.mail.deleteMailboxWebmailKey(mailbox.mail_engine_account_id, key.keyId).catch(() => undefined);
    const winner = await one<CredentialRow>(ctx.db, 'SELECT mailbox_id, engine_key_id, secret_encrypted FROM mailbox_webmail_credentials WHERE mailbox_id = ?', [mailbox.id]);
    if (!winner) throw new WebmailError('unavailable', 'Could not establish a mailbox credential. Try again.');
    return ctx.secrets.decrypt(winner.secret_encrypted);
  }
  return key.secret;
}

/** Revokes the engine key and forgets the local secret. The next webmail use creates a fresh key. */
export async function rotateWebmailCredential(ctx: AppContext, mailbox: { id: string; mail_engine_account_id: string | null }): Promise<void> {
  const existing = await one<CredentialRow>(ctx.db, 'SELECT mailbox_id, engine_key_id, secret_encrypted FROM mailbox_webmail_credentials WHERE mailbox_id = ?', [mailbox.id]);
  if (existing && mailbox.mail_engine_account_id) {
    await ctx.mail.deleteMailboxWebmailKey(mailbox.mail_engine_account_id, existing.engine_key_id).catch((err) => {
      ctx.log.warn({ mailboxId: mailbox.id, err: (err as Error).message }, 'webmail key revocation failed');
    });
  }
  await exec(ctx.db, 'DELETE FROM mailbox_webmail_credentials WHERE mailbox_id = ?', [mailbox.id]);
}

export async function buildWebmailMailbox(ctx: AppContext, mailbox: { id: string; normalized_address: string; mail_engine_account_id: string | null }): Promise<WebmailMailbox> {
  const credential = await ensureWebmailCredential(ctx, mailbox);
  return { mailboxId: mailbox.id, address: mailbox.normalized_address, engineId: mailbox.mail_engine_account_id!, credential };
}

/** Updates the last-used marker no more than once a minute to avoid write amplification. */
export async function touchWebmailCredential(ctx: AppContext, mailboxId: string): Promise<void> {
  await exec(ctx.db, 'UPDATE mailbox_webmail_credentials SET last_used_at = NOW(3) WHERE mailbox_id = ? AND (last_used_at IS NULL OR last_used_at < DATE_SUB(NOW(3), INTERVAL 1 MINUTE))', [mailboxId]);
}
